contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 amount) public {
        uint256 balBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);
        uint256 supplyBefore = c.totalSupply();
        bool reverted;
        bool ok;
        try c.transfer(to, amount) returns (bool r) { reverted = false; ok = r; }
        catch { reverted = true; ok = false; }
        uint256 balAfter = c.balanceOf(address(this));
        uint256 toAfter = c.balanceOf(to);
        uint256 supplyAfter = c.totalSupply();
        assert(
            (reverted == (amount > balBefore)) &&
            (reverted || (ok && supplyAfter == supplyBefore && toAfter == toBefore + amount && balAfter + amount == balBefore + amount))
        );
    }
    receive() external payable {}
}

